import type { JsonValue } from "./json.js";
export type FileType = "docker" | "tilt" | "config" | "prisma" | "generated" | "unknown";
export interface AutogeneratedFile {
    name: string;
    path: string;
    type: FileType;
    size: number;
    lastModified: string;
}
export type ResourceFileType = "json" | "text";
export interface FileGenerationTask {
    type: ResourceFileType;
    filename: string;
    content: JsonValue;
    description: string;
    emoji: string;
}
export interface FileNode {
    name: string;
    path: string;
    type: "directory" | "file";
    fileType?: FileType;
    children?: FileNode[];
    size?: number;
    lastModified?: string;
}
